package app.snaptocart.kroger;
import app.snaptocart.config.AppProperties; import org.springframework.stereotype.Service; import java.net.URLEncoder; import java.nio.charset.StandardCharsets; import java.util.Map;
@Service public class KrogerService { private final AppProperties p; public KrogerService(AppProperties p){this.p=p;} public Map<String,String> connectUrl(){if(p.krogerClientId()==null||p.krogerClientId().isBlank())throw new IllegalStateException("Kroger credentials are not configured");String scope="cart.basic:write profile.compact";String url="https://api.kroger.com/v1/connect/oauth2/authorize?client_id="+enc(p.krogerClientId())+"&redirect_uri="+enc(p.krogerRedirectUri())+"&response_type=code&scope="+enc(scope);return Map.of("url",url);} public Map<String,Object> add(String upc,int quantity){if(p.demoMode())return Map.of("status","demo-added","upc",upc,"quantity",quantity);throw new IllegalStateException("Connect Kroger OAuth before adding items");} private String enc(String x){return URLEncoder.encode(x,StandardCharsets.UTF_8);} }
